<?php $priorities=rows('SELECT * FROM notification_priorities ORDER BY id'); ?>
<section class="panel"><h2>Create notification</h2><form method="post" action="action.php" enctype="multipart/form-data" class="form-stack"><?= csrf_field() ?><input type="hidden" name="action" value="send_notification"><label>Title<input name="title" maxlength="150" required></label><label>Message (description)<textarea name="message" rows="4" maxlength="10000" required></textarea></label><div class="form-grid"><label>Recipient Group<select name="recipient_type" id="recipient-type"><?php options(['All','Specific','Custom'],'All'); ?></select></label><label>Priority<select name="priority_id" required><?php foreach($priorities as $priority): ?><option value="<?= (int)$priority['id'] ?>"><?= e($priority['name']) ?></option><?php endforeach; ?></select></label></div><div id="resident-picker" hidden><label>Find a resident<input type="search" id="recipient-search" placeholder="Filter by name or email"></label><fieldset><legend>Select residents</legend><div class="resident-picker-list"><?php foreach(rows("SELECT id,first_name,last_name,email FROM users WHERE role='resident' ORDER BY last_name,first_name") as $resident): ?><label class="recipient-choice"><input type="checkbox" name="recipients[]" value="<?= (int)$resident['id'] ?>"><?= e($resident['first_name'].' '.$resident['last_name'].' · '.$resident['email']) ?></label><?php endforeach; ?></div></fieldset></div><label>Add Documents (optional attachment, up to 5 MB)<input type="file" name="attachment" accept=".pdf,.jpg,.jpeg,.png,.docx"></label><button class="button primary">Send Notification</button></form></section>
<section class="panel dashboard-actions"><h2>Recent notifications</h2><?php foreach(rows('SELECT a.*,p.name priority,(SELECT COUNT(*) FROM notifications n WHERE n.announcement_id=a.id) recipients FROM announcements a JOIN notification_priorities p ON p.id=a.priority_id ORDER BY a.id DESC LIMIT 5') as $item): ?><article class="announcement"><h3><?= e($item['title']) ?> <span class="badge"><?= e($item['priority']) ?></span></h3><p><?= nl2br(e($item['message'])) ?></p><small><?= e($item['created_at']) ?> · <?= (int)$item['recipients'] ?> recipients · <?= e($item['recipient_type']) ?></small><?php if($item['attachment_path']): ?><p><a href="../attachment.php?announcement=<?= (int)$item['id'] ?>">Download <?= e($item['attachment_name']) ?></a></p><?php endif; ?></article><?php endforeach; ?></section>
<section class="panel dashboard-actions"><h2>Notifications delivered to residents</h2><div class="table-scroll"><table><thead><tr><th>Recipient</th><th>Title</th><th>Message</th><th>Sent</th><th>Read</th></tr></thead><tbody><?php foreach(rows('SELECT n.*,u.first_name,u.last_name FROM notifications n JOIN users u ON u.id=n.user_id ORDER BY n.id DESC LIMIT 100') as $n): ?><tr><td><?= e($n['first_name'].' '.$n['last_name']) ?></td><td><?= e($n['title']) ?></td><td><?= e($n['message']) ?></td><td><?= e($n['created_at']) ?></td><td><?= $n['read_at']?'Read':'Unread' ?></td></tr><?php endforeach; ?></tbody></table></div><p class="muted">Showing the latest 100 deliveries.</p></section>
